/** `collections` (templates round 24): a shop's own collections, so the links its menus give (/collections/<handle>) open a page with its products; each lists products by title. The fixtures' shared three are kept beside them. */
export interface SampleCollection { handle: string; title: string; description: string; products: string[] }
