  /* Templates round 23: Northpaper, one Notion template's sales page: Offer Board, a job search tracker, with an interview kit and a bundle. Every picture is a Notion page drawn for the template and photographed on a tablet or phone. */
  /* Templates round 24: the product is now Creator OS, a Notion system for content creators. */
  notionpage: {
    name: "Northpaper",
    products: [
      { title: "Creator OS", price: "$29.00", compare: "$39.00", image: "notionpage-creator-os.webp", kind: "digital", description: "A Notion template for content creators: a dashboard, an idea bank by stage, a script page for every video, a content calendar for every platform, a sponsor pipeline, analytics and a weekly review. You get a link that duplicates it into your own workspace, and it works on Notion's free plan.", options: [{ name: "Edition", values: ["Template", "Template and sponsor kit"] }], add: { "Template and sponsor kit": 10 } },
      { title: "Sponsor Kit", price: "$19.00", image: "notionpage-sponsor-kit.webp", kind: "digital", description: "A Notion sponsor pipeline with a rate card, a media kit page, five pitch emails and a checklist for every deliverable, from the first email to the paid invoice." },
      { title: "The Creator Bundle", price: "$39.00", compare: "$48.00", image: "notionpage-bundle.webp", kind: "digital", description: "Creator OS and the Sponsor Kit together, linked so every deal sits beside the video it pays for." },
    ],
    posts: [
      { title: "How to plan a month of content in one sitting", tag: "Planning", image: "notionpage-post-calendar.webp", excerpt: "Empty the idea bank, score what is there and give every week one main post. A Sunday routine that covers four weeks.", html: `<p>Planning a week at a time means deciding what to make on the day you should be making it. One longer sitting a month moves that decision out of the way.</p><h2 id="empty">Empty the idea bank</h2><p>Put every idea from your notes app, voice memos and screenshots on one board. Score each one out of ten for how much you want to make it and how much your audience asked for it.</p><h2 id="pick">Pick one main post a week</h2><ul><li>One main video, episode or issue for each of the four weeks</li><li>Two or three shorts cut from each main post</li><li>A spare idea in case a shoot falls through</li></ul><h2 id="date">Put dates on everything</h2><p>Give each post a film date and a publish date on the calendar. The gap between them is your editing time.</p>` },
      { title: "Keeping track of sponsor deals without a spreadsheet", tag: "Sponsors", image: "notionpage-post-sponsors.webp", excerpt: "One row per deal, with the fee, the deliverable and the date the brand needs a draft. What to log and when to chase.", html: `<p>Sponsor deals go wrong in the gaps: a draft date in an email thread, an invoice nobody sent. One table closes most of them.</p><h2 id="columns">What each row needs</h2><ul><li>Brand and the person you talk to</li><li>Stage: pitched, negotiating, signed, draft sent, invoice sent, paid</li><li>The fee and the deliverable, in one line</li><li>The draft date and the publish date</li></ul><h2 id="chase">When to chase</h2><p>Look at the table every Friday. Anything past its date gets a short, friendly email the same day.</p>` },
      { title: "A weekly review for creators in twenty minutes", tag: "Weekly review", image: "notionpage-post-review.webp", excerpt: "Look back, plan, chase. The Friday routine that keeps a channel moving without taking over the weekend.", html: `<p>A channel slows down when nobody looks at it as a whole. Twenty minutes on Friday is enough.</p><h2 id="back">Look back</h2><p>Log views and subscribers for each post that went out. Mark the best and the worst and write one line on why.</p><h2 id="plan">Plan</h2><p>Pick next week's main post and its shorts, and move finished edits to scheduled.</p><h2 id="chase">Chase</h2><p>Send any sponsor drafts that are due and any invoices that are not paid.</p>` },
    ],
  },
